### Phase 1: CORS Middleware
I will implement a middleware that performs exact-match validation against a whitelist of origins. This ensures that even if a subdomain is compromised, it cannot access the API unless explicitly permitted.

#### Step 1.1: Implementation
I'll create the middleware in `internal/gateway/middleware/cors.go`.

```go
// internal/gateway/middleware/cors.go
package middleware

import (
	"net/http"
	"strings"
)

type CORSConfig struct {
	AllowedOrigins   []string
	AllowedMethods   []string
	AllowedHeaders   []string
	AllowCredentials bool
}

func NewCORS(config CORSConfig) func(http.Handler) http.Handler {
	// Convert allowed origins to a map for O(1) lookup and exact matching
	origins := make(map[string]bool)
	for _, o := range config.AllowedOrigins {
		origins[strings.ToLower(o)] = true
	}

	methods := strings.Join(config.AllowedMethods, ", ")
	headers := strings.Join(config.AllowedHeaders, ", ")

	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			origin := r.Header.Get("Origin")

			// Exact match check
			if origins[strings.ToLower(origin)] {
				w.Header().Set("Access-Control-Allow-Origin", origin)
				if config.AllowCredentials {
					w.Header().Set("Access-Control-Allow-Credentials", "true")
				}
				w.Header().Set("Access-Control-Allow-Methods", methods)
				w.Header().Set("Access-Control-Allow-Headers", headers)
			}

			// Handle preflight
			if r.Method == http.MethodOptions {
				w.WriteHeader(http.StatusNoContent)
				return
			}

			next.ServeHTTP(w, r)
		})
	}
}
```

