// internal/gateway/middleware/cors_test.go
package middleware

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestCORSMiddleware(t *testing.T) {
	config := CORSConfig{
		AllowedOrigins: []string{"https://app.example.com", "https://admin.example.com"},
		AllowedMethods: []string{"GET", "POST"},
	}
	mw := NewCORS(config)
	handler := mw(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
	}))

	tests := []struct {
		name           string
		origin         string
		expectedHeader string
	}{
		{"Exact Match", "https://app.example.com", "https://app.example.com"},
		{"Unauthorized Subdomain", "https://attacker.example.com", ""},
		{"Partial Match Attempt", "https://app.example.com.evil.com", ""},
		{"Case Insensitive Match", "HTTPS://APP.EXAMPLE.COM", "HTTPS://APP.EXAMPLE.COM"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			req := httptest.NewRequest("GET", "/", nil)
			req.Header.Set("Origin", tt.origin)
			rec := httptest.NewRecorder()

			handler.ServeHTTP(rec, req)

			got := rec.Header().Get("Access-Control-Allow-Origin")
			if got != tt.expectedHeader {
				t.Errorf("Expected origin %q, got %q", tt.expectedHeader, got)
			}
		})
	}
}
```

