```go
// internal/service/account_service.go

package service

import (
	"context"
	"errors"
	"log"

	"github.com/your-repo/gen/accountpb" // Generated from account_service.proto
	"github.com/your-repo/internal/domain"
)

type AccountService struct {
	accountpb.UnimplementedAccountServiceServer
	repo domain.AccountRepository
}

func NewAccountService(repo domain.AccountRepository) *AccountService {
	return &AccountService{repo: repo}
}

func (s *AccountService) UpdateAccount(ctx context.Context, req *accountpb.UpdateAccountRequest) (*accountpb.UpdateAccountResponse, error) {
	// 1. Fetch existing account
	existing, err := s.repo.GetByID(ctx, req.Id)
	if err != nil {
		return nil, err
	}

	// 2. Handle Partial Patch Logic for Status
	// In proto3 'optional' fields, HasStatus() or checking for nil pointers is used
	if req.Status != nil {
		newStatus := req.GetStatus() // "ACTIVE" or "INACTIVE"
		if !isValidStatus(newStatus) {
			return nil, errors.New("invalid status value")
		}
		existing.Status = newStatus
	}

	// 3. Update other fields...
	if req.DisplayName != "" {
		existing.DisplayName = req.DisplayName
	}

	// 4. Persist
	updated, err := s.repo.Update(ctx, existing)
	if err != nil {
		return nil, err
	}

	return &accountpb.UpdateAccountResponse{
		Account: mapDomainToProto(updated),
	}, nil
}

func isValidStatus(s string) bool {
	return s == "ACTIVE" || s == "INACTIVE"
}

func mapDomainToProto(a *domain.Account) *accountpb.Account {
	return &accountpb.Account{
		Id:          a.ID,
		Status:      &a.Status,
		DisplayName: a.DisplayName,
	}
}
```

