// src/middleware/authV2.ts

export const authMiddlewareV2 = (req, res, next) => {
  // 1. Reject legacy X-API-Key immediately
  if (req.headers['x-api-key']) {
    return res.status(401).json({
      error: "Deprecated Authentication",
      message: "X-API-Key is no longer supported. Please use OAuth2 Bearer tokens."
    });
  }

  // 2. Enforce Bearer Token
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: "Missing or invalid Authorization header" });
  }

  const token = authHeader.split(' ')[1];
  // Proceed to JWT validation...
  next();
};
