### 2. Developer: Implementation (WT-002)
I am implementing the core transfer logic. I will use a "Lock-Order" utility to ensure we always acquire row locks in the same sequence.

**Service Logic (TypeScript/TypeORM-style pseudo-code):**
```typescript
class WalletTransferService {
  async transfer(dto: TransferRequest): Promise<TransferResult> {
    const { fromId, toId, amount, idempotencyKey } = dto;

    return await db.transaction(async (manager) => {
      // 1. Deterministic Lock Ordering
      const [firstId, secondId] = [fromId, toId].sort();

      // 2. Acquire Row Locks (SELECT FOR UPDATE)
      // We lock the smaller ID first to prevent deadlocks
      const accountsMap = new Map();
      const firstAccount = await manager.createQueryBuilder(Account, "acc")
        .setLock("pessimistic_write")
        .where("acc.id = :id", { id: firstId })
        .getOne();

      const secondAccount = await manager.createQueryBuilder(Account, "acc")
        .setLock("pessimistic_write")
        .where("acc.id = :id", { id: secondId })
        .getOne();

      accountsMap.set(firstAccount.id, firstAccount);
      accountsMap.set(secondAccount.id, secondAccount);

      const sender = accountsMap.get(fromId);
      const receiver = accountsMap.get(toId);

      // 3. Business Logic Validations
      if (sender.balance < amount) {
        throw new Error("INSUFFICIENT_FUNDS");
      }

      // 4. Atomic Updates
      sender.balance -= amount;
      receiver.balance += amount;

      await manager.save(sender);
      await manager.save(receiver);

      // 5. Create Audit Trail (Transfer & Ledger)
      const transfer = await manager.save(Transfer, {
        from_account_id: fromId,
        to_account_id: toId,
        amount,
        idempotency_key: idempotencyKey,
        status: 'COMPLETED'
      });

      await manager.save(LedgerEntry, [
        { transfer_id: transfer.id, account_id: fromId, amount: -amount },
        { transfer_id: transfer.id, account_id: toId, amount: amount }
      ]);

      return { transferId: transfer.id, status: 'SUCCESS' };
    });
  }
}
```

