I will use **Go** for this implementation, as it is the industry standard for high-performance API Gateways. We will implement two middleware components: `CORSMiddleware` (with strict anchor matching) and `RateLimitMiddleware`.

### 1. Implementation: `internal/middleware/security.go`

```go
package middleware

import (
	"net/http"
	"strconv"
	"sync"
	"time"
)

// --- CORS MIDDLEWARE ---

type CORSSettings struct {
	AllowedOrigins map[string]bool
}

func NewCORSMiddleware(origins []string) func(http.Handler) http.Handler {
	allowed := make(map[string]bool)
	for _, o := range origins {
		allowed[o] = true
	}

	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			origin := r.Header.Get("Origin")

			// Strict exact match check
			if allowed[origin] {
				w.Header().Set("Access-Control-Allow-Origin", origin)
				w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS")
				w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization")
			}

			// Handle Preflight
			if r.Method == http.MethodOptions {
				w.WriteHeader(http.StatusNoContent)
				return
			}

			next.ServeHTTP(w, r)
		})
	}
}

// --- RATE LIMIT MIDDLEWARE ---

type Visitor struct {
	lastSeen time.Time
	count    int
}

var (
	visitors = make(map[string]*Visitor)
	mu       sync.Mutex
)

func RateLimitMiddleware(limit int, window time.Duration) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			ip := r.RemoteAddr // In production, use X-Forwarded-For

			mu.Lock()
			v, exists := visitors[ip]
			if !exists || time.Since(v.lastSeen) > window {
				visitors[ip] = &Visitor{lastSeen: time.Now(), count: 1}
				v = visitors[ip]
			} else {
				v.count++
			}

			remaining := limit - v.count
			reset := window - time.Since(v.lastSeen)
			mu.Unlock()

			// Set standard headers
			w.Header().Set("X-RateLimit-Limit", strconv.Itoa(limit))
			w.Header().Set("X-RateLimit-Remaining", strconv.Itoa(max(0, remaining)))
			w.Header().Set("X-RateLimit-Reset", strconv.Itoa(int(reset.Seconds())))

			if remaining < 0 {
				http.Error(w, "Too Many Requests", http.StatusTooManyRequests)
				return
			}

			next.ServeHTTP(w, r)
		})
	}
}

func max(a, b int) int {
	if a > b { return a }
	return b
}
```

