		{"Invalid Subdomain", "https://malicious.example.com", http.StatusOK, false},
		{"Partial Match Attempt", "https://app.example.com.attacker.com", http.StatusOK, false},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			req := httptest.NewRequest("GET", "/", nil)
			req.Header.Set("Origin", tt.origin)
			rr := httptest.NewRecorder()

			handler.ServeHTTP(rr, req)

			hasHeader := rr.Header().Get("Access-Control-Allow-Origin") != ""
			if hasHeader != tt.expectHeader {
				t.Errorf("CORS header presence mismatch: expected %v, got %v", tt.expectHeader, hasHeader)
			}
		})
	}
}

