	log.Printf("Starting PaymentReceivedEvent consumer...")
	for {
		m, err := c.reader.FetchMessage(ctx)
		if err != nil {
			if ctx.Err() != nil {
				return ctx.Err()
			}
			log.Printf("error fetching message: %v", err)
			continue
		}

		var event events.PaymentReceivedEvent
		if err := proto.Unmarshal(m.Value, &event); err != nil {
			log.Printf("error unmarshaling event: %v", err)
			// Commit invalid messages to avoid blocking the partition
			c.reader.CommitMessages(ctx, m)
			continue
		}

		// Process with idempotency and ordering logic
		if err := c.repo.ProcessPayment(ctx, &event); err != nil {
			log.Printf("failed to process payment %s: %v", event.PaymentId, err)
			// Depending on error type, we might want to NOT commit to trigger retry
			// For this implementation, we assume repo handles retriable vs non-retriable
			continue
		}

		if err := c.reader.CommitMessages(ctx, m); err != nil {
			log.Printf("failed to commit message: %v", err)
		}
	}
