package repository

import (
	"context"
	"database/sql"
	"errors"
	"time"

	"github.com/org/repo/proto/events"
)

type PostgresPaymentRepo struct {
	db *sql.DB
}

func (r *PostgresPaymentRepo) ProcessPayment(ctx context.Context, event *events.PaymentReceivedEvent) error {
	// Use a transaction to ensure atomicity
	tx, err := r.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()

	// 1. Idempotency & Ordering Check
	// We check if we've already processed this payment or if a newer update exists.
	// occurred_at_ms handles out-of-order retries.
	var lastProcessedAt int64
	err = tx.QueryRowContext(ctx, 
		"SELECT last_event_timestamp FROM payment_processing_log WHERE payment_id = $1", 
		event.PaymentId).Scan(&lastProcessedAt)

	if err == nil {
		// Event already processed or newer event exists
		if lastProcessedAt >= event.OccurredAtMs {
			return nil // Already handled, skip
		}
	} else if !errors.Is(err, sql.ErrNoRows) {
		return err
	}

	// 2. Update Payment State
	_, err = tx.ExecContext(ctx, `
		INSERT INTO payments (id, amount_cents, currency, status, updated_at)
		VALUES ($1, $2, $3, 'RECEIVED', $4)
		ON CONFLICT (id) DO UPDATE SET
			status = 'RECEIVED',
			updated_at = $4
		WHERE payments.updated_at < $4`, // Ensure we don't overwrite with older data
		event.PaymentId, event.AmountCents, event.Currency, time.UnixMilli(event.OccurredAtMs))
	if err != nil {
		return err
	}

	// 3. Record processing to log for idempotency
	_, err = tx.ExecContext(ctx, `
		INSERT INTO payment_processing_log (payment_id, last_event_timestamp)
		VALUES ($1, $2)
		ON CONFLICT (payment_id) DO UPDATE SET
			last_event_timestamp = EXCLUDED.last_event_timestamp
		WHERE payment_processing_log.last_event_timestamp < EXCLUDED.last_event_timestamp`,
		event.PaymentId, event.OccurredAtMs)
	if err != nil {
		return err
	}

	return tx.Commit()
}
```

### Summary of Safety Measures:
1.  **`FetchMessage` + `CommitMessages`**: Manual offset management ensures we only commit after successful DB write.
2.  **`ON CONFLICT` + `WHERE` clause**: Prevents overwriting newer data with older retried events (Out-of-order handling).
3.  **Transaction**: Ensures that the payment update and the processing log update happen atomically.
4.  **Proto-first**: Uses generated Go structs from Protobuf for strict data contract.

