    secondID := req.DestinationUserId

    if firstID == secondID {
        return nil, errors.New("cannot transfer to the same account")
    }

    // Sort IDs to ensure consistent locking order across all concurrent requests
    if firstID > secondID {
        firstID, secondID = secondID, firstID
    }

    tx, err := s.db.BeginTx(ctx, nil)
    if err != nil {
        return nil, err
    }
    defer tx.Rollback()

    // 2. Acquire locks in the sorted order
    // SELECT ... FOR UPDATE ensures we hold the lock until the transaction ends
    _, err = tx.ExecContext(ctx, "SELECT 1 FROM accounts WHERE user_id = $1 FOR UPDATE", firstID)
    if err != nil {
