	if req.AmountCents <= 0 {
		return nil, errors.New("transfer amount must be positive")
	}
	if req.SourceUserId == req.DestinationUserId {
		return nil, errors.New("source and destination accounts must be different")
	}

	tx, err := s.db.BeginTx(ctx, &sql.TxOptions{Isolation: sql.LevelReadCommitted})
	if err != nil {
		return nil, err
	}
	defer tx.Rollback()

	// 1. Deterministic Lock Ordering
	firstID, secondID := req.SourceUserId, req.DestinationUserId
	if firstID > secondID {
		firstID, secondID = secondID, firstID
	}

	// Lock both rows in order
	for _, id := range []string{firstID, secondID} {
		_, err := tx.ExecContext(ctx, "SELECT 1 FROM accounts WHERE user_id = $1 FOR UPDATE", id)
		if err != nil {
			return nil, fmt.Errorf("failed to lock account %s: %w", id, err)
		}
	}

	// 2. Check Source Balance
	var sourceBalance int64
	err = tx.QueryRowContext(ctx, "SELECT balance_cents FROM accounts WHERE user_id = $1", req.SourceUserId).Scan(&sourceBalance)
	if err != nil {
		return nil, fmt.Errorf("failed to fetch source balance: %w", err)
	}

	if sourceBalance < req.AmountCents {
		return nil, errors.New("insufficient funds")
	}

